import{_ as o,o as d,c as t,a2 as c}from"./chunks/framework.Cw6yz976.js";const g=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/changelog.md","filePath":"en/guide/changelog.md","lastUpdated":1790377022000}'),a={name:"en/guide/changelog.md"};function i(n,e,r,s,l,h){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p><a href="./CHANGELOG">English</a> | <a href="./CHANGELOG.zh-CN">中文</a></p><h2 id="_1-9-0" tabindex="-1">1.9.0 <a class="header-anchor" href="#_1-9-0" aria-label="Permalink to &quot;1.9.0&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>TCP sockets (native, no third-party deps)</strong>: <code>#tcp_connect(host; port)</code>, <code>#tcp_listen(port)</code>, <code>#tcp_accept(srv)</code>, <code>#tcp_send(sock; data)</code>, <code>#tcp_recv(sock; maxlen)</code>, <code>#tcp_close(sock)</code> — listen / accept / send / receive for building custom servers and clients; handles are plain ints, work across <code>#thread</code> workers (Windows winsock + POSIX sockets)</li><li><strong>File / folder encryption</strong>: <code>#encrypt_file(path; key)</code> / <code>#decrypt_file(path; key)</code> encrypt/restore a single file in place (AES-256-CBC, base64 ciphertext); <code>#encrypt_dir(dir; key)</code> / <code>#decrypt_dir(dir; key)</code> recurse a whole folder; <code>VSENC1</code> magic prefix makes wrong-key decryption fail loudly</li><li>VSCode extension 0.9.0 (syntax highlighting for the 10 new builtins)</li></ul><h2 id="_1-8-0" tabindex="-1">1.8.0 <a class="header-anchor" href="#_1-8-0" aria-label="Permalink to &quot;1.8.0&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>vpm validation hardening</strong>: <ul><li>Zip extraction is scanned for path-traversal (<code>..</code>) and absolute-path entries before install — malicious packages are rejected and cleaned up</li><li><code>entry</code> in <code>vesna-pkg.json</code> may only be a plain filename (no <code>..</code>, drive letter, or path separators)</li><li><code>registry.json</code> cache is structure-validated on every load; a corrupt cache is reported, deleted and re-downloaded</li><li>Local cache: downloaded packages are cached to <code>packages\\_cache\\&lt;name&gt;-&lt;ver&gt;.zip</code>; a sha256-matching cache installs <strong>offline</strong> (no network)</li></ul></li><li><strong>LSP v1.8.0</strong>: <code>textDocument/definition</code> (go-to-definition), <code>textDocument/signatureHelp</code> (parameter hints for builtins and user functions), <code>workspace/symbol</code> (cross-document symbols); server version bumped</li><li><strong><code>#sha256</code></strong> now accepts a byte list: <code>#sha256(#bin_read(path))</code> hashes the real file bytes (previously <code>#fread</code> text-mangled binary)</li><li>VSCode extension 0.8.0: LSP startup failure shows an actionable message (config <code>vesna.executablePath</code>)</li></ul><h2 id="_1-7-0" tabindex="-1">1.7.0 <a class="header-anchor" href="#_1-7-0" aria-label="Permalink to &quot;1.7.0&quot;">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Single-file distribution</strong> — the standard library (<code>csv.ves</code> / <code>json.ves</code> / <code>pkg.ves</code> / <code>stat.ves</code> / <code>text.ves</code>, ~19 KB) is now embedded into the executable. <code>vesna.exe</code> runs standalone with no <code>lib/</code> directory, no <code>VESNA_HOME</code> and no other files — copy one exe and everything works (including <code>--pkg</code>). External <code>lib/</code> files still take precedence, so users can still override modules by dropping a <code>.ves</code> next to their script or in <code>lib/</code>.</li><li>Version bump to 1.7.0.</li></ul><h2 id="_1-6-0" tabindex="-1">1.6.0 <a class="header-anchor" href="#_1-6-0" aria-label="Permalink to &quot;1.6.0&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong><code>#http_server(port; &quot;handler&quot;)</code></strong> — a blocking HTTP server (native sockets, no dependencies). Each request builds <code>req = {method; path; headers; body}</code> and calls the handler by name; the handler returns a string (200) or <code>{code; body; type}</code> for full control</li><li><strong>Time builtins</strong>: <code>#date_format(ts; fmt)</code> formats any unix timestamp (default <code>%Y-%m-%d %H:%M:%S</code>); <code>#parse_time(s; fmt)</code> parses a formatted string back to a timestamp (<code>%Y %m %d %H %M %S</code> subset, separator-tolerant)</li><li><strong><code>#uuid()</code></strong> — random UUID v4 (36 chars, RFC-4122 variant/version bits)</li><li><strong>File builtins</strong>: <code>#file_time(path)</code> returns the last-modified unix time; <code>#truncate(path; size)</code> truncates or extends a file to the given byte size</li><li><strong><code>#arch()</code></strong> — <code>&quot;x64&quot;</code> / <code>&quot;arm64&quot;</code> / <code>&quot;x86&quot;</code> / <code>&quot;unknown&quot;</code> (runtime platform detection is <code>#platform()</code> since 0.4)</li><li>Syntax highlighting extended to all 183 builtins</li></ul><h2 id="_1-5-0" tabindex="-1">1.5.0 <a class="header-anchor" href="#_1-5-0" aria-label="Permalink to &quot;1.5.0&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>vpm publish</strong>: <code>vesna --pkg publish</code> — one command to publish a package: validates <code>vesna-pkg.json</code>, packs <code>entry</code> + metadata into <code>&lt;name&gt;-&lt;version&gt;.zip</code> (PowerShell <code>Compress-Archive</code> on Windows / <code>zip</code> elsewhere), computes the zip <code>sha256</code>, writes <code>registry-entry.json</code>, and updates a local <code>registry.json</code> if present</li><li><strong><code>#call(fname; arg...)</code> builtin</strong> (dispatch 176): dynamic function invocation by name string — enables package frameworks like the new <code>vesna-test</code> test framework</li><li><strong><code>vesna-test</code> package 1.0.0</strong>: unit test framework (<code>test_case(name; &quot;fn&quot;)</code>, <code>test_run()</code>, <code>test_eq</code>, <code>test_assert</code>, <code>test_true</code>, <code>test_count</code>) — published to the vesna-pkg registry</li><li><strong>Import respects package <code>entry</code></strong>: <code>import</code> now reads <code>vesna-pkg.json</code>&#39;s <code>entry</code> field for vpm packages (previously only <code>&lt;package-name&gt;.ves</code> was tried); imported package globals can also see caller script functions via the parent env chain</li><li><strong><code>vesna --fmt &lt;file&gt;</code></strong>: source formatter — normalizes indentation (<code>-</code> runs), trims trailing whitespace, collapses blank lines (syntax-preserving, line-level only)</li><li><strong>Syntax highlighting 1.1-1.4</strong>: <code>vesna.tmLanguage.json</code> builtin patterns extended to all 176 builtins (thread/lock/http/bin/json/crypto/proc/ffi/csv/ini/xml/call)</li><li><strong>REPL Tab completion</strong> (Windows): type <code>#js&lt;Tab&gt;</code> etc. — unique match auto-completes, multiple matches list candidates</li></ul><h2 id="_1-4-0" tabindex="-1">1.4.0 <a class="header-anchor" href="#_1-4-0" aria-label="Permalink to &quot;1.4.0&quot;">​</a></h2><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Native C++ LSP</strong>: <code>vesna.exe --lsp</code> — a built-in Language Server (stdio JSON-RPC) with diagnostics (reuses the C++ <code>Parser</code> error collection), completion (all builtins from the single name table plus document identifiers, <code>#</code> trigger), hover (builtin/keyword docs + function defs), <code>documentSymbol</code> (functions) and <code>foldingRange</code> (indent blocks)</li><li><strong>VSCode extension 0.5.0</strong>: <code>vesna-0.5.0.vsix</code> — server now spawns <code>vesna --lsp</code> (no Python dependency); the Python LSP server directory was removed</li><li><strong>Tier-4 builtins</strong> (dispatch 170-175): <code>#csv_parse(s)</code> → row/field list, <code>#csv_build(rows)</code> → CSV text (RFC-4180 quoting), <code>#ini_read(path)</code> / <code>#ini_write(path; data)</code> (section/key/value, <code>;</code> <code>#</code> comments), <code>#xml_parse(s)</code> → simple DOM <code>{tag; attrs; children; text}</code> (attributes, nesting, self-closing tags, <code>&amp;amp;</code> <code>&amp;lt;</code> <code>&amp;gt;</code> <code>&amp;quot;</code> <code>&amp;apos;</code>), <code>#ffi_call_s(dll; func; arg...)</code> → <code>char*</code> result as string</li><li><strong>CI fixes</strong>: compile now links <code>-lws2_32</code> (1.1 networking builtins); golden regression extended with tier3 / binary / tier4; concurrency run check; vpm validation smoke; LSP smoke drives the compiled <code>vesna.exe --lsp</code>; <code>release.yml</code> aligned to 1.4.0 (<code>vesna-0.5.0.vsix</code>, <code>-lws2_32</code>, bilingual README/CHANGELOG/CONTRIBUTING + RELEASE-NOTES)</li><li><strong>Single source of truth for builtins</strong>: the 175-entry name table <code>g_builtinNames</code> now drives the lexer&#39;s builtin set, the dispatch map, and LSP completion (previously three hand-maintained tables)</li></ul><h2 id="_1-3-1" tabindex="-1">1.3.1 <a class="header-anchor" href="#_1-3-1" aria-label="Permalink to &quot;1.3.1&quot;">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><code>--install</code> now works when run from the <code>bin\\</code> directory of a release package (the installer auto-detects a trailing <code>\\bin</code> in the current directory and walks up to the package root). Previously it errored with &quot;找不到 bin\\vesna.exe&quot;.</li></ul><h2 id="_1-3-0-1-3-0" tabindex="-1">1.3.0## 1.3.0 <a class="header-anchor" href="#_1-3-0-1-3-0" aria-label="Permalink to &quot;1.3.0## 1.3.0&quot;">​</a></h2><h3 id="added-5" tabindex="-1">Added <a class="header-anchor" href="#added-5" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>vpm validation</strong> (<code>lib/pkg.ves</code>): metadata checks (<code>name</code> <code>^[a-z][a-z0-9_-]+$</code>, <code>version</code> <code>x.y.z</code>, <code>entry</code> must exist), optional <code>sha256</code> integrity verification from registry entries, automatic dependency installation with version checks and loop protection, and <code>remove</code> dependency guard (<code>--force</code> overrides). <code>init [name]</code> now validates the package name.</li><li><strong>LSP 0.4.0</strong> (<code>vesna-vscode/server</code>): parser synced to the frozen 1.0.0 reference (full 0.4 syntax diagnostics); completion covers all 169 builtins (1.1/1.2 tiers included); hover with builtin/keyword docs; <code>documentSymbol</code> (functions); <code>foldingRange</code> (indent blocks); <code>#</code> completion trigger.</li><li><strong>VSCode extension 0.4.0</strong>: <code>vesna-0.4.0.vsix</code>, serverInfo 0.4.0, new description.</li></ul><h2 id="_1-2-0-1-2-0" tabindex="-1">1.2.0## 1.2.0 <a class="header-anchor" href="#_1-2-0-1-2-0" aria-label="Permalink to &quot;1.2.0## 1.2.0&quot;">​</a></h2><h3 id="added-6" tabindex="-1">Added <a class="header-anchor" href="#added-6" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Data builtins</strong>: <code>#json_encode(v)</code> / <code>#json_decode(s)</code> (native JSON, dicts keep insertion order), <code>#re_groups(s; pattern)</code> (regex capture groups, unmatched groups are <code>none</code>)</li><li><strong>Crypto builtins</strong>: <code>#sha256(s)</code> (verified against FIPS 180-4 vectors), <code>#aes_encrypt(data; key)</code> / <code>#aes_decrypt(b64; key)</code> (AES-256-CBC + PKCS7, SHA-256-derived key, base64 output, verified against FIPS-197); new pure-C++ <code>src/cpp/crypto.h</code> with <code>crypto_selftest.cpp</code> vector checks</li><li><strong>Process builtin</strong>: <code>#proc_run(cmd)</code> returns <code>{&quot;exit&quot;: code; &quot;output&quot;: stdout}</code></li><li><strong>FFI</strong>: <code>#ffi_call(&quot;dll&quot;; &quot;func&quot;; arg...)</code> — call C functions from shared libraries (Windows x64 LoadLibrary/GetProcAddress; Linux/macOS dlopen/dlsym); args: int / string (<code>char*</code>), up to 6 args, 64-bit integer result</li><li>New smoke test <code>tests/tier3.ves</code> (+ <code>tier3_data.json</code>) with C++-generated golden</li></ul><h2 id="_1-1-0-1-1-0" tabindex="-1">1.1.0## 1.1.0 <a class="header-anchor" href="#_1-1-0-1-1-0" aria-label="Permalink to &quot;1.1.0## 1.1.0&quot;">​</a></h2><h3 id="added-7" tabindex="-1">Added <a class="header-anchor" href="#added-7" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Concurrency builtins</strong>: <code>#thread(&quot;fn&quot;; arg...)</code> (run a function in a new thread with an isolated copy of global variables; returns a thread id), <code>#thread_join(id)</code> (wait and collect the <code>back</code> value, rethrowing the thread&#39;s error), <code>#thread_count()</code>, <code>#lock(&quot;name&quot;)</code> / <code>#unlock(&quot;name&quot;)</code> (named mutexes for shared resources); <code>print</code> output is serialized and unjoined threads are joined at exit</li><li><strong>Networking builtins</strong> (require <code>curl</code> in PATH): <code>#http_get(url)</code>, <code>#http_post(url; body)</code>, <code>#tcp_ping(host; port)</code> (native TCP probe via Winsock on Windows / BSD sockets elsewhere)</li><li><strong>Binary builtins</strong>: <code>#bin_read(path)</code> / <code>#bin_write(path; bytes)</code> (byte lists), <code>#bin_hex(bytes)</code> / <code>#bin_unhex(s)</code>, <code>#bin_base64_encode(bytes)</code> / <code>#bin_base64_decode(s)</code> — bytes are plain ints so existing list ops apply</li><li>New smoke tests <code>tests/concurrency.ves</code> / <code>tests/binary.ves</code> with C++-generated golden baselines (the frozen Python reference has no 1.1 builtins)</li></ul><h2 id="_1-0-0-1-0-0" tabindex="-1">1.0.0## 1.0.0 <a class="header-anchor" href="#_1-0-0-1-0-0" aria-label="Permalink to &quot;1.0.0## 1.0.0&quot;">​</a></h2><h3 id="added-8" tabindex="-1">Added <a class="header-anchor" href="#added-8" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Package manager (vpm)</strong>: <code>vesna --pkg</code> — init / install (<code>dir</code> | <code>zip</code> | <code>owner:repo</code> | registry package name) / remove / list / search / registry; packages live in <code>&lt;VESNA_HOME&gt;\\packages\\&lt;name&gt;\\&lt;name&gt;.ves</code> and are imported via <code>import &lt;name&gt;</code>; <code>install &lt;name&gt;</code> resolves the package from the cached registry index; default registry is the <a href="https://youakasakura-YAS.github.io/vesna-pkg/" target="_blank" rel="noreferrer">Vesna Package Garden</a></li><li><strong>Debugger</strong>: <code>vesna --debug</code> — breakpoints (<code>b</code> / <code>del</code>), continue / next / step, expression eval (<code>p</code>), variables (<code>vars</code>), backtrace (<code>bt</code>), source listing (<code>list</code>); pauses on the first line by default</li><li>New builtin <code>#cpdir(src; dst)</code>: recursively copy a directory</li><li><strong>Cross-platform</strong>: new <code>src/cpp/platform.h</code> abstraction (UTF-8/16 conversion, shell, cwd, chdir, environment, temp dir); CMake build for Windows / Linux / macOS; registry builtins (<code>-regwrite</code> / <code>-regdelete</code> / <code>-regenv</code>) report &quot;not supported&quot; on non-Windows; <code>#platform</code> returns <code>windows</code> / <code>linux</code> / <code>mac</code></li><li>Examples golden baselines are now generated by the C++ implementation (authoritative; the Python reference is frozen for regression only)</li><li><strong>General-purpose expansion</strong>: 70 new builtins <ul><li>Math: <code>#sqrt</code> <code>#floor</code> <code>#ceil</code> <code>#exp</code> <code>#log</code> <code>#log10</code> <code>#sin</code> <code>#cos</code> <code>#tan</code> <code>#sign</code> <code>#clamp</code> <code>#rand</code> <code>#randint</code> <code>#choice</code> <code>#shuffle</code></li><li>Number bases: <code>#hex</code> <code>#bin</code> <code>#oct</code></li><li>Strings: <code>#pad</code> <code>#lpad</code> <code>#rpad</code> <code>#format</code> <code>#hash</code></li><li>Lists: <code>#range</code> <code>#first</code> <code>#last</code> <code>#take</code> <code>#drop</code> <code>#set</code> <code>#flatten</code> <code>#zip</code> <code>#insert</code> <code>#remove</code> <code>#index_of</code> <code>#enumerate</code> <code>#concat</code></li><li>Dicts: <code>#get</code> <code>#items</code> <code>#pop_key</code></li><li>Type checks: <code>#is_str</code> <code>#is_int</code> <code>#is_float</code> <code>#is_bool</code> <code>#is_list</code> <code>#is_dict</code> <code>#is_none</code> <code>#is_group</code></li><li>Time &amp; system: <code>#now</code> <code>#date</code> <code>#sleep</code> <code>#ticks</code> <code>#platform</code> <code>#temp_dir</code></li><li>Files: <code>#fremove</code> <code>#fmove</code> <code>#fsize</code> <code>#is_dir</code> <code>#is_file</code> <code>#mkdirs</code></li><li>Encoding: <code>#base64_encode</code> <code>#base64_decode</code> <code>#url_encode</code> <code>#url_decode</code></li><li>Functional: <code>#each</code> <code>#all</code> <code>#any</code> <code>#find_first</code> <code>#sort_by</code></li><li>Exceptions: <code>#throw</code> <code>#assert</code></li></ul></li><li>CI adds a golden comparison step for the 0.4 builtin smoke test (<code>tests/smoke04.ves</code>)</li><li>New builtin <code>#regenv(name)</code>: read a user environment variable (<code>HKCU\\Environment</code>)</li><li><code>vesna --uninstall</code>: removes the install directory, cleans <code>VESNA_HOME</code> / <code>PATH</code>, and deletes the <code>.ves</code> / <code>VesnaScript</code> registry association</li><li><code>--install</code> now also writes the <code>OpenWithProgids</code> entry (previously only in <code>install-assoc.reg</code>), fully integrating the association into the installer</li><li><code>#regdelete</code> now deletes the whole key tree recursively</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Version bumped to 1.0.0</li><li><code>#format</code> supports precision (<code>%.2f</code>) in addition to <code>%s</code> <code>%d</code> <code>%f</code> <code>%%</code></li></ul><h2 id="_0-3-0" tabindex="-1">0.3.0 <a class="header-anchor" href="#_0-3-0" aria-label="Permalink to &quot;0.3.0&quot;">​</a></h2><h3 id="added-9" tabindex="-1">Added <a class="header-anchor" href="#added-9" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Builtins <code>#regwrite</code>, <code>#regdelete</code>, <code>#shell</code>, <code>#path_clean</code></li><li><code>vesna --install</code> with <code>.ves</code> file-association registration</li><li><code>vesna --version</code>, <code>vesna --help</code></li><li>File-type icons, &quot;Run with Vesna&quot; context menu, New-file menu</li><li><strong>C++ implementation</strong> (<code>src/cpp/</code>, statically linked, line-by-line compatible with the Python reference)</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Version bumped to 0.3.0</li><li>Comment parsing no longer strips <code>/* */</code> inside strings</li><li><code>if</code>/<code>while</code> conditions now use truthiness (0/empty is falsy)</li><li>File/registry/shell builtins throw catchable errors via <code>try/catch</code></li><li>Trailing tokens after assignment statements are rejected (previously silently ignored)</li><li>Removed dead code branches; added argument boundary checks</li></ul><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Installer is written entirely in Vesna</li><li>C++ performance optimizations (grep 100k lines: ~2s → ~240ms): <ul><li>Regex cache and literal fast paths</li><li>Zero-copy variable lookup (<code>Env::getRef</code>)</li><li><code>Value</code> as <code>std::variant</code> (~104 → ~40 bytes)</li><li>Identifier interning (names → integer IDs)</li><li>Builtin dispatch: if-chain → hash map + switch</li><li><code>-O3 -flto</code> build; iostream/C-stdio sync disabled</li></ul></li></ul><h2 id="_0-2-0" tabindex="-1">0.2.0 <a class="header-anchor" href="#_0-2-0" aria-label="Permalink to &quot;0.2.0&quot;">​</a></h2><h3 id="added-10" tabindex="-1">Added <a class="header-anchor" href="#added-10" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Bytecode: none yet, currently AST evaluation</li><li>70+ builtins</li><li>Standard library: csv, json, text, stat</li><li>Tool set: wc, grep, head, tail, sort, uniq, cut, sed, replace, stat, logstat, csv2json, extract</li><li>VSCode syntax highlighting + LSP</li><li>Standalone <code>vesna.exe</code></li></ul><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Builtin prefix changed from <code>-</code> to <code>#</code></li><li><code>elif</code> / <code>else</code> at the same level as <code>if</code></li><li><code>-push</code> renamed to <code>-append</code></li></ul><h2 id="_0-1-0" tabindex="-1">0.1.0 <a class="header-anchor" href="#_0-1-0" aria-label="Permalink to &quot;0.1.0&quot;">​</a></h2><p>Initial version.</p>',51)])])}const p=o(a,[["render",i]]);export{g as __pageData,p as default};
